-- Тема 19: правки по отчёту Codex (25 исправлений в 15 вопросах), ключи не меняются.
-- Источник: scripts/questions/091_codex_topic19_fixes.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('question', 'Программа получила новую анонимную область памяти через mmap и впервые записывает в одну из её страниц. Что верно?', NULL, NULL, NULL, 'Программа получила через mmap новую анонимную область с правом записи, без MAP_POPULATE, и впервые записывает в одну из её страниц. Что верно?'),
        ('question', 'Когда в программе на C имеет смысл читать errno?', NULL, NULL, NULL, 'Когда в программе на C имеет смысл читать errno после вызова write()?'),
        ('question', 'Через какие системные вызовы malloc получает память у ядра в Linux?', NULL, NULL, NULL, 'Через какие системные вызовы штатный malloc из glibc получает память у ядра в Linux?'),
        ('question', 'Как postmaster обслуживает новое подключение клиента в Linux?', NULL, NULL, NULL, 'Как postmaster стандартной сборки PostgreSQL 16 для Linux обслуживает новое подключение клиента?'),
        ('question', 'В /proc/PID/syscall обслуживающего процесса PostgreSQL первое поле равно 232. Что это значит?', NULL, NULL, NULL, 'В /proc/PID/syscall обслуживающего процесса PostgreSQL на Linux x86-64 первое поле равно 232. Что это значит?'),
        ('option', 'Зачем ядру нужно регулярное прерывание от таймера?', 'Чтобы регулярно получать управление над процессором', NULL, 'Так работает вытесняющая многозадачность: ядро отдаёт процессор другим задачам, даже если программа не делает системных вызовов, и зависшая программа не захватит его навсегда.', 'Так работает вытесняющая многозадачность: ядро отдаёт процессор другим задачам, даже если программа не делает системных вызовов, и зависшая программа не захватит его навсегда. В режимах NO_HZ ядро подавляет лишние срабатывания таймера, когда это возможно.'),
        ('option', 'Программа получила через mmap новую анонимную область с правом записи, без MAP_POPULATE, и впервые записывает в одну из её страниц. Что верно?', 'Возникает страничная ошибка — исключение процессора', NULL, 'Страница пока есть только в виде адресов, в таблице страниц её нет.', 'Готового отображения этой страницы в таблице страниц ещё нет, поэтому процессор вызывает исключение.'),
        ('option', 'Программа получила через mmap новую анонимную область с правом записи, без MAP_POPULATE, и впервые записывает в одну из её страниц. Что верно?', 'Процесс получает сигнал SIGSEGV из-за доступа вне области', NULL, 'Адрес принадлежит процессу и доступ разрешён, поэтому ядро просто выдаёт страницу.', 'Адрес принадлежит процессу и запись разрешена, поэтому ядро просто выдаёт страницу.'),
        ('explanation', 'Программа получила через mmap новую анонимную область с правом записи, без MAP_POPULATE, и впервые записывает в одну из её страниц. Что верно?', NULL, NULL, 'С новой областью mmap так бывает всегда; malloc же может вернуть уже использованную память, а glibc сама пишет служебные данные в начало блока. Мелкие страничные ошибки обходятся без диска, крупные требуют чтения из файла или свопа. Счётчики процесса: ps -o pid,min_flt,maj_flt,cmd -p PID. Опыт 4 в examples/syscalls.c считает их при записи в 64 МБ.', 'Так работает выделение памяти по требованию, если страницы не подготовлены заранее (MAP_POPULATE, огромные страницы THP); malloc же может вернуть уже использованную память, а glibc сама пишет служебные данные в начало блока. Мелкие страничные ошибки обходятся без диска, крупные требуют чтения из файла или свопа. Счётчики процесса: ps -o pid,min_flt,maj_flt,cmd -p PID. Опыт 4 в examples/syscalls.c считает их при записи в 64 МБ.'),
        ('option', 'Что такое системный вызов?', 'Обращение программы к ядру за запрещённым ей действием', 'Обращение программы к ядру за выполнением услуги', 'Программа просит ядро выполнить действие, которое ей запрещено в пользовательском режиме. Например, записать файл, получить память или создать процесс.', 'Это контролируемый вход в ядро: программа просит выполнить то, что сама сделать не может, например записать файл, получить память или создать процесс. Права ядро проверяет само и может вернуть ошибку.'),
        ('explanation', 'Что такое системный вызов?', NULL, NULL, 'В Linux около 350 системных вызовов. Список с описаниями: man 2 syscalls; описание одного вызова: man 2 write.', 'Список системных вызовов с описаниями: man 2 syscalls; описание одного вызова: man 2 write. Их число зависит от версии ядра и архитектуры.'),
        ('option', 'Что верно для функции write() в программе на C?', 'printf вызывает её сразу при каждом обращении к нему', NULL, 'printf копит данные в буфере и вызывает write реже.', 'printf может буферизовать вывод и не обязан вызывать write при каждом обращении; когда буфер сбрасывается, зависит от режима буферизации потока.'),
        ('option', 'Программа вызывает функции open() и fork(), а в выводе strace видны openat и clone. Почему?', 'Обёртки glibc open() и fork() вызывают openat и clone', NULL, 'Функции glibc open() и fork() выполняют системные вызовы openat и clone. Имена обёрток и вызовов ядра совпадают не всегда.', 'В современных glibc обёртки open() и fork() выполняют системные вызовы openat и clone (open так работает с glibc 2.26). Имена обёрток и вызовов ядра совпадают не всегда.'),
        ('explanation', 'Как на Linux x86-64 программа сообщает ядру, какой системный вызов нужен?', NULL, NULL, 'Номера зависят от архитектуры процессора. Значение от -4095 до -1 в rax означает ошибку. Таблица номеров: man 2 syscall; на учебной машине номер, в котором ждёт процесс: cat /proc/PID/syscall.', 'Номера зависят от архитектуры процессора. Значение от -4095 до -1 в rax означает ошибку. Соглашение о вызове: man 2 syscall, номера — константы SYS_* в sys/syscall.h; на учебной машине номер, в котором ждёт процесс: cat /proc/PID/syscall.'),
        ('option', 'Когда в программе на C имеет смысл читать errno после вызова write()?', 'Только после вызовов printf и других функций вывода', 'Перед вызовом: errno подскажет, удастся ли запись', 'errno заполняют многие функции и системные вызовы.', 'errno описывает уже случившуюся ошибку, а не предсказывает следующую.'),
        ('option', 'Когда в программе на C имеет смысл читать errno после вызова write()?', 'Только после сообщения функции об ошибке, например -1', 'После того как write вернула -1, до других вызовов', 'errno объясняет причину уже случившейся ошибки; при успешном вызове его значение не определено.', 'При -1 write сообщает причину в errno; следующие вызовы могут её перезаписать, поэтому код сохраняют сразу. После успешного write значение errno ничего не говорит об этой записи.'),
        ('option', 'Что такое файловый дескриптор?', 'Номер открытого файла или канала в таблице процесса', NULL, 'Дальше программа обращается к файлу по этому номеру. Номер возвращает open, а открытым может быть файл, канал или сокет.', 'Дальше программа обращается к файлу по этому номеру. Дескрипторы возвращают open, pipe, socket, accept и другие вызовы; за номером может стоять файл, канал или сокет.'),
        ('option', 'Что верно для системных вызовов fork и execve?', 'PostgreSQL в Linux запускает обслуживающий процесс через fork и execve', 'Стандартная сборка PostgreSQL для Linux запускает обслуживающий процесс через fork и execve', 'В Linux postmaster вызывает только fork: копия сразу работает как обслуживающий процесс.', 'В стандартной сборке postmaster вызывает только fork: копия сразу работает как обслуживающий процесс. execve после fork добавляет лишь особая сборка с EXEC_BACKEND.'),
        ('option', 'Что значит состояние Z у процесса в выводе ps?', 'Процесс завершился, родитель ещё не вызвал wait', 'Процесс завершился, родитель не забрал его статус', 'Процесс завершился, но родитель ещё не забрал его код завершения вызовом wait. Такой процесс называют зомби: память освобождена, осталась только запись о нём.', 'Родитель ещё не получил статус завершения этого ребёнка вызовом из семейства wait (wait, waitpid, waitid). Такой процесс называют зомби: память освобождена, осталась только запись о нём.'),
        ('option', 'Как postmaster стандартной сборки PostgreSQL 16 для Linux обслуживает новое подключение клиента?', 'Запускает новую программу postgres вызовом execve для клиента', NULL, 'В Linux postmaster вызывает только fork, без execve.', 'В стандартной сборке для Linux postmaster вызывает только fork, без execve; execve добавляет лишь особая сборка с EXEC_BACKEND.'),
        ('option', 'Команда time показала: real 2.1s, user 0.4s, sys 1.6s. Что это значит?', 'Большую часть времени программа провела в режиме ядра', 'Большая часть процессорного времени ушла на режим ядра', NULL, NULL),
        ('option', 'Команда time показала: real 2.1s, user 0.4s, sys 1.6s. Что это значит?', 'Программа работала в 1.6 потоках на нескольких ядрах процессора', 'Программа 0.4 секунды ждала процессора, 1.6 — работала', 'sys — время, а не число потоков.', 'user — процессорное время в пользовательском режиме, а не ожидание процессора.'),
        ('explanation', 'Команда time показала: real 2.1s, user 0.4s, sys 1.6s. Что это значит?', NULL, NULL, 'Сравните на любой машине: time dd if=/dev/zero of=/dev/null bs=1 count=1000000 и time dd if=/dev/zero of=/dev/null bs=1000000 count=1. Объём одинаковый, а sys различается на порядки.', 'На ядро пришлось 1.6 / (0.4 + 1.6) = 80 % процессорного времени; real 2.1 с — время по часам, его нельзя напрямую сравнивать с суммой user и sys. Сравните на любой машине: time dd if=/dev/zero of=/dev/null bs=1 count=1000000 и time dd if=/dev/zero of=/dev/null bs=1000000 count=1. Объём одинаковый, а sys различается на порядки.'),
        ('option', 'Что верно для утилиты strace?', 'Безопасна для рабочего сервера PostgreSQL в часы нагрузки', NULL, 'Замедление и раскрытие данных делают её инструментом учебной машины.', 'Подключение strace замедляет процесс и может раскрыть данные, поэтому в практикуме её запускают на учебной машине.'),
        ('option', 'Что верно для утилиты strace?', 'Может вывести данные программы, в том числе пароли и запросы', NULL, 'Содержимое данных, в том числе пароли и тексты запросов, попадает в вывод, поэтому необработанный вывод чужих программ не публикуют.', 'В зависимости от вызовов и фильтров в вывод могут попасть содержимое данных, пароли и тексты запросов, поэтому необработанный вывод чужих программ не публикуют.')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
